import{D as t}from"./chunks/DemoVideo.Cxll-bB3.js";import{o as s,c as i,a2 as a,E as n}from"./chunks/framework.2Gs1zKBA.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"use-cases/collision-detection.md","filePath":"use-cases/collision-detection.md","lastUpdated":1794555138000}'),l={name:"use-cases/collision-detection.md"},h=Object.assign(l,{setup(d){return(o,e)=>(s(),i("div",null,[e[0]||(e[0]=a(`<h2 id="碰撞检测" tabindex="-1">碰撞检测 <a class="header-anchor" href="#碰撞检测" aria-label="Permalink to &quot;碰撞检测&quot;">​</a></h2><p>本案例在规划运动中启用多策略碰撞检测，通过力矩变化率和关节功率异常识别接触，并在触发后记录碰撞事件、停止运动和失能机械臂。默认使用 MuJoCo 注入力矩冲击；确认无误后，才可在符合示例安装条件的真机上验证。</p><div class="danger custom-block"><p class="custom-block-title">真机操作提示</p><p>碰撞检测是接触后的软件启发式检测，不是几何避障，也不是经过安全认证的保护停止。真机测试只能使用固定、柔软的泡棉障碍物；不得用人体、手持物或刚性物体主动碰撞机械臂。测试前必须固定并支撑机械臂，清空无关人员和物品，确保现场紧急停止及断电措施可用。</p></div><h3 id="演示目标" tabindex="-1">演示目标 <a class="header-anchor" href="#演示目标" aria-label="Permalink to &quot;演示目标&quot;">​</a></h3><p>示例依次完成以下流程：</p><ol><li>创建 A1R，按右肩垂直安装配置使能机械臂并设置中等刚度；</li><li>启用 Impact 和 Energy 两个检测通道，同时配置自动停止与事件回调；</li><li>让指定关节在限位内运动；仿真模式约 1.6 秒后自动注入力矩冲击；</li><li>触发时输出检测通道、关节、强度和停止位置；</li><li>未触发时完成整段运动并报告结果；</li><li>结束时失能机械臂并关闭通信。</li></ol><p>Impact 和 Energy 通道不依赖精确动力学模型或已知负载。阈值仍会受到安装方式、刚度、速度、工具、负载和传动状态影响，必须针对实际设备验证。</p><h3 id="安装与准备" tabindex="-1">安装与准备 <a class="header-anchor" href="#安装与准备" aria-label="Permalink to &quot;安装与准备&quot;">​</a></h3><p>进入 <code>onero-sdk</code> 仓库并安装仿真依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/workspace/onero-sdk</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.[sim]&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>真机运行前还需要完成 <a href="/onerobot-A1/getting-started/hardware">CAN 接口配置与连接检查</a>，并逐项确认：</p><ul><li>设备是 A1R，安装方向与示例的 <code>humanoid_right</code> 一致；</li><li>基座、线缆和柔软泡棉障碍物均可靠固定，失能后机械臂仍有可靠支撑；</li><li>目标关节、运动方向和完整扫掠范围已经在无障碍条件下检查；</li><li>已先用默认仿真确认检测与停止流程；</li><li>操作者知道真机模式没有运动前确认提示，运行命令后会直接使能并开始运动。</li></ul><p>安装方式、型号或测试姿态不一致时，不得直接运行真机命令；应先修改并重新验证示例配置。</p><h3 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th style="text-align:right;">默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>--real</code></td><td style="text-align:right;">关闭</td><td>添加后连接真机；不添加时运行 MuJoCo</td></tr><tr><td><code>--channel</code></td><td style="text-align:right;"><code>can0</code></td><td>真机 SocketCAN 通道</td></tr><tr><td><code>--joint</code></td><td style="text-align:right;"><code>2</code></td><td>运动关节，范围 J1～J7</td></tr><tr><td><code>--amplitude</code></td><td style="text-align:right;"><code>1.0</code></td><td>关节运动幅度，单位 rad；程序会按剩余行程选择正向或反向</td></tr><tr><td><code>--impact-threshold</code></td><td style="text-align:right;"><code>80</code></td><td>Impact 通道阈值；越低越敏感，也越容易误报</td></tr><tr><td><code>--energy-threshold</code></td><td style="text-align:right;"><code>25</code></td><td>Energy 通道阈值；越低越敏感，也越容易误报</td></tr></tbody></table><p>示例还固定使用 <code>min_velocity=0.05</code>、<code>warmup_frames=100</code> 和 <code>CollisionResponse.BOTH</code>。预热期间不会触发；<code>BOTH</code> 表示触发时既执行回调，也通过 SDK 紧急停止路径立即失能电机。示例阈值只是演示起点，不是安全额定值。</p><h3 id="mujoco-仿真" tabindex="-1">MuJoCo 仿真 <a class="header-anchor" href="#mujoco-仿真" aria-label="Permalink to &quot;MuJoCo 仿真&quot;">​</a></h3><p>默认运行不连接真机：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/25_collision_detection.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://github.com/lvwenyi01/onero-sdk/blob/main/examples/25_collision_detection.py" target="_blank" rel="noreferrer">查看完整源码</a></p><p>程序让 J2 运动，并在约 1.6 秒后向同一关节注入力矩冲击。正常输出应包含：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>碰撞检测已启用: impact=80, energy=25</span></span>
<span class="line"><span>J2 将运动 ... rad</span></span>
<span class="line"><span>仿真将在约 1.6 秒后注入力矩冲击...</span></span>
<span class="line"><span>&gt;&gt;&gt; 碰撞触发: impact, J2, 强度 ...x</span></span>
<span class="line"><span>机械臂已停止: ... &gt; 80.0</span></span>
<span class="line"><span>演示结束，机械臂已自动失能。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>仿真注入只验证检测、回调和停止流程，不能证明同一阈值适合真机，也不能模拟现场障碍物的材料、形状和接触位置。</p><h3 id="真机验证" tabindex="-1">真机验证 <a class="header-anchor" href="#真机验证" aria-label="Permalink to &quot;真机验证&quot;">​</a></h3><p>先在无障碍条件下运行一次，确认运动方向、完整路径和默认阈值不会误报：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/25_collision_detection.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --real</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> can0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>无碰撞时应完成运动并输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运动完成，未检测到碰撞。</span></span>
<span class="line"><span>演示结束，机械臂已自动失能。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>随后固定柔软泡棉障碍物，在保持人员远离运动区域的条件下再次运行。接触后应在到达目标前停止，并输出触发通道、关节、强度、阈值和停止位置。输出数值取决于实际接触，不应与视频逐值比较。</p><p>若泡棉接触未触发，只能小幅降低 <code>--impact-threshold</code>，每次调整后都必须先做无障碍运动检查误报。不得通过换用更硬障碍物、增大速度或反复撞击来寻找阈值。</p><h3 id="演示视频" tabindex="-1">演示视频 <a class="header-anchor" href="#演示视频" aria-label="Permalink to &quot;演示视频&quot;">​</a></h3><p>视频先展示一次无障碍运动，再展示 Impact 通道检测到 J2 接触并停止。视频中的接触方式仅用于记录已有测试结果。</p>`,32)),n(t,{src:"/videos/cases/25_collision_detection.mp4",title:"碰撞检测真机演示"}),e[1]||(e[1]=a('<h3 id="结果判断" tabindex="-1">结果判断 <a class="header-anchor" href="#结果判断" aria-label="Permalink to &quot;结果判断&quot;">​</a></h3><p>运行成功应同时满足：</p><ul><li>无障碍运行完成，且没有误报；</li><li>仿真冲击或真机泡棉接触发生后，目标运动提前结束；</li><li>回调中的通道、关节和强度与停止信息一致；</li><li><code>last_collision</code> 能返回本次碰撞事件及停止位置；</li><li>程序最终输出机械臂已经失能。</li></ul><p>若无障碍运动误报，应检查阈值、安装方向、刚度、工具、负载、线缆拖拽和反馈噪声。若明显接触未触发，应先检查关节速度是否低于 <code>min_velocity</code>、检测通道是否覆盖当前运动接口以及参数是否生效，不能直接把碰撞检测用于人员防护。</p><h3 id="覆盖范围与安全边界" tabindex="-1">覆盖范围与安全边界 <a class="header-anchor" href="#覆盖范围与安全边界" aria-label="Permalink to &quot;覆盖范围与安全边界&quot;">​</a></h3><p>自动检测覆盖 <code>movej()</code>、<code>movel()</code>、、<code>movec()</code>、<code>speedj()</code> 和 <code>speedl()</code> 产生的规划运动；不覆盖 <code>servoj()</code>、<code>servop()</code> 或主动接触的 <code>force_mode()</code>。回调在控制循环线程中执行，只能做快速记录或通知，不能执行阻塞操作。</p><p>碰撞检测不包含桌面、墙体、工具或另一条机械臂的几何模型，无法在接触前规划无碰撞路径。需要几何避障时，应使用 <a href="/onerobot-A1/use-cases/moveit2">MoveIt 2 运动控制</a> 或应用层规划器。</p><h3 id="中断与安全状态" tabindex="-1">中断与安全状态 <a class="header-anchor" href="#中断与安全状态" aria-label="Permalink to &quot;中断与安全状态&quot;">​</a></h3><p>检测触发且响应包含停止时，SDK 进入紧急停止路径并立即失能电机；这与 <code>stop()</code> 的减速停止不同。无碰撞的正常路径会显式调用 <code>disable()</code>。真机运行发生其他异常时，示例也会调用 <code>emergency_stop()</code>；无论哪种失能路径，机械臂都会撤销保持力矩，必须继续提供可靠支撑。</p><p>关闭通信或仿真窗口不等于停止运动或失能。重新运行前必须确认机械臂已经停止、障碍物已经移除，并查明误报、漏报或异常停止原因。</p><h2 id="标定入口" tabindex="-1">标定入口 <a class="header-anchor" href="#标定入口" aria-label="Permalink to &quot;标定入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>目的</th><th>示例入口</th></tr></thead><tbody><tr><td>软件零位</td><td>建立可复现的用户关节零位</td><td><a href="/onerobot-A1/advanced/#软件零位">软件零位说明</a></td></tr><tr><td>动力学标定</td><td>辨识惯性和关节摩擦参数</td><td><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/15_dynamics_calibration.py" target="_blank" rel="noreferrer">动力学标定示例</a></td></tr><tr><td>运动学标定</td><td>修正关节原点并改善模型一致性</td><td><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/16_kinematic_calibration.py" target="_blank" rel="noreferrer">运动学标定示例</a></td></tr><tr><td>手眼标定</td><td>求解相机与法兰或基座之间的变换</td><td><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/17_camera_calibration.py" target="_blank" rel="noreferrer">手眼标定示例</a></td></tr></tbody></table><p>标定文件不得在不同机械臂、序列号、安装方向或工具配置之间直接复用。</p><h3 id="结果判断-1" tabindex="-1">结果判断 <a class="header-anchor" href="#结果判断-1" aria-label="Permalink to &quot;结果判断&quot;">​</a></h3><p>力控运行成功应同时满足：</p><ul><li>三组场景按顺序完成，接触力方向与所选坐标系一致；</li><li>进入和退出接触过程平稳，没有振荡、冲击或持续位置漂移；</li><li>每个场景结束后退出力控，最后返回关节零位；</li><li>终端没有通信、限位或动力学异常。</li></ul><p>标定结果还应按类型判断：动力学标定的 <code>residual_rms</code> 是力矩模型拟合残差，不是末端定位精度；运动学标定的 <code>residual_mm</code> 只描述采集触点的模型收敛程度，必须使用独立检测点验证；手眼标定还需要相机内参、同步采集和未参与求解的数据验证。</p><p>所有标定结果都应与型号、序列号、左右侧、安装方向、工具、固件和 SDK 版本一起保存。</p><h3 id="中断与安全状态-1" tabindex="-1">中断与安全状态 <a class="header-anchor" href="#中断与安全状态-1" aria-label="Permalink to &quot;中断与安全状态&quot;">​</a></h3><p>若接触力方向错误、工具滑动、接触面松动或机械臂出现振荡，应立即使用现场适用的安全措施。不能通过增大目标力、延长持续时间或提高刚度来绕过异常。</p><p>程序正常结束或发生异常时会调用 <code>disable()</code>；这会撤销保持力矩，不是普通停止。异常发生在力控循环内时，不应仅依赖终端退出判断设备状态，必须现场确认机械臂已经停止并得到可靠支撑。</p><p>完整流程、参数边界和常见问题见<a href="/onerobot-A1/advanced/#标定">示教、力控与标定</a>。</p>',22))]))}});export{c as __pageData,h as default};
